using Captovix;
using System.Windows;
using System.Windows.Media;
internal static class Program
{
    [STAThread]static int Main(){try{var app=new Application();int w=80,h=60;var pixels=Enumerable.Repeat((byte)255,w*h*4).ToArray();var image=ImageTransfer.Bitmap(w,h,pixels);
        for(int mode=0;mode<=5;mode++){var window=new ImageWorkshop(image,mode);window.Close();Console.WriteLine("PASS: Workshop constructor/close mode "+mode);}
        var doc=new EditorDocument{OriginalWidth=w,OriginalHeight=h,SourceHash="fixture",PixelBasePng=RasterPixels.Encode(image)};var layer=new Annotation{Kind=AnnotationKind.ImageLayer,PixelPng=RasterPixels.Encode(image),X2=w,Y2=h,ImageStyle=new(){Mask=LayerMask.Ellipse,Opacity=.5}};doc.Annotations.Add(layer);doc.Validate(w,h,"fixture");if(doc.Version!=15)throw new Exception("New mask/opacity document must reject downgrade");var session=new EditorSession(doc);session.Change(d=>d.PixelBasePng=RasterPixels.Encode(ImageTransfer.Bitmap(w,h,ImageStudioPixels.Adjust(pixels,w,h,20,0,0,0,0))));session.Undo();if(RasterPixels.Source(image,session.Document).PixelWidth!=w)throw new Exception("Undo dimensions");
        // Regression: save a schema15 sidecar twice and after loading it again.
        string originalPath=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"captovix-save-"+Guid.NewGuid().ToString("N")+".png");ImageTransfer.Save(image,originalPath);string hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.IO.File.ReadAllBytes(originalPath)));session.Document.SourceHash=hash;var item=new MediaItem{Id=Guid.NewGuid().ToString("N"),FilePath=originalPath};string sidecar=DocumentStore.EditPath(item.Id);
        try{DocumentStore.Save(item,session,image);DocumentStore.Save(item,session,image);var reopened=DocumentStore.Load(item,image,out var warning);if(warning!=null||reopened.Document.Version!=15)throw new Exception("Schema15 reopen failed");DocumentStore.Save(item,reopened,image);var future=reopened.Document.Clone();future.Version=EditorDocument.MaximumSupportedVersion+1;string futureBytes=future.Serialize();System.IO.File.WriteAllText(sidecar,futureBytes);bool blocked=false;try{DocumentStore.Save(item,reopened,image);}catch(System.IO.InvalidDataException){blocked=true;}if(!blocked||System.IO.File.ReadAllText(sidecar)!=futureBytes)throw new Exception("Future sidecar must remain byte-identical");Console.WriteLine("PASS: save twice/reopen/save schema15 and preserve future sidecar");}finally{System.IO.File.Delete(originalPath);System.IO.File.Delete(sidecar);System.IO.File.Delete(DocumentStore.ThumbnailPath(item.Id));}
        var render=EditorRenderer.Render(image,session.Document);if(render.PixelWidth!=w||render.PixelHeight!=h)throw new Exception("Mask resized output");
        var batch=BatchRendering.Transform(image,new(Watermark:"HV",WatermarkPosition:0,WatermarkOpacity:.5));var bytes=ImageTransfer.Bgra(batch);if(!bytes.AsSpan((w*h-1)*4,4).SequenceEqual(pixels.AsSpan((w*h-1)*4,4)))throw new Exception("Watermark changed unedited corner");Console.WriteLine("PASS: document, undo, output size, watermark preserves untouched pixel");return 0;
    }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
